values = [" 203.0.113.10 ", "EXAMPLE.ORG", "https://example.org/path", "a"*64, "analyst@example.org"]

def classify(value):
    raw = value
    v = value.strip()
    if IPV4.fullmatch(v) and all(0 <= int(p) <= 255 for p in v.split('.')):
        return raw, v, "ipv4"
    if SHA256.fullmatch(v):
        return raw, v.lower(), "sha256"
    if EMAIL.fullmatch(v):
        return raw, v.lower(), "email"
    if v.startswith(("http://","https://")):
        return raw, v, "url"
    if DOMAIN.fullmatch(v.lower().rstrip('.')):
        return raw, v.lower().rstrip('.'), "domain"
    return raw, v, "unknown"

