#!/usr/bin/env python3
"""Local vendor-neutral CTI fusion pipeline using only Python stdlib."""
from __future__ import annotations
import argparse
import json
import re
import sys
from dataclasses import dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

ALLOWED_TYPES={"ipv4","domain","url","sha256"}
ALLOWED_TLP={"TLP:RED","TLP:AMBER","TLP:GREEN","TLP:CLEAR"}
CONF={"low":0.4,"medium":0.7,"high":1.0}
SHA256_RE=re.compile(r"^[0-9a-f]{64}$")
IPV4_RE=re.compile(r"^(?:\d{1,3}\.){3}\d{1,3}$")
DOMAIN_RE=re.compile(r"^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$",re.I)

@dataclass(frozen=True)
class Observation:
    type:str
    value:str
    source:str
    confidence:str
    tlp:str
    observed_at:datetime
    actionability:float
    evidence:str
    attck:tuple[str,...]
    context:str

    @property
    def normalized_value(self)->str:
        value=self.value.strip()
        if self.type in {"domain","sha256"}:
            value=value.lower().rstrip(".")
        return value


def parse_time(value:str)->datetime:
    return datetime.fromisoformat(value.replace("Z","+00:00")).astimezone(timezone.utc)


def validate_indicator(kind:str,value:str)->None:
    if kind not in ALLOWED_TYPES:
        raise ValueError(f"unsupported indicator type: {kind}")
    if kind=="sha256" and not SHA256_RE.fullmatch(value.lower()):
        raise ValueError("invalid SHA-256")
    if kind=="ipv4":
        if not IPV4_RE.fullmatch(value) or not all(0<=int(x)<=255 for x in value.split(".")):
            raise ValueError("invalid IPv4")
    if kind=="domain" and not DOMAIN_RE.fullmatch(value.lower().rstrip(".")):
        raise ValueError("invalid domain")
    if kind=="url" and not value.startswith(("http://","https://")):
        raise ValueError("URL must use http or https")


def parse_observation(raw:dict[str,Any],now:datetime)->Observation:
    required=("type","value","source","confidence","tlp","observed_at","actionability","evidence")
    missing=[x for x in required if raw.get(x) in (None,"")]
    if missing:
        raise ValueError("missing: "+", ".join(missing))
    if raw["confidence"] not in CONF:
        raise ValueError("confidence must be low, medium, or high")
    if raw["tlp"] not in ALLOWED_TLP:
        raise ValueError("unsupported TLP")
    observed_at=parse_time(raw["observed_at"])
    if observed_at>now:
        raise ValueError("observed_at cannot be in the future")
    value=str(raw["value"]).strip()
    validate_indicator(raw["type"],value)
    action=float(raw["actionability"])
    if not 0<=action<=1:
        raise ValueError("actionability must be between 0 and 1")
    if raw["evidence"] not in {"observed","inferred"}:
        raise ValueError("evidence must be observed or inferred")
    return Observation(raw["type"],value,str(raw["source"]),raw["confidence"],raw["tlp"],observed_at,action,raw["evidence"],tuple(raw.get("attck",[])),str(raw.get("context","")))


def freshness(now:datetime,observed_at:datetime,half_life_days:float=30.0)->float:
    age=max(0.0,(now-observed_at).total_seconds()/86400.0)
    return 0.5**(age/half_life_days)


def priority_score(obs:Observation,now:datetime)->float:
    evidence_factor=1.0 if obs.evidence=="observed" else 0.7
    score=100*(0.40*CONF[obs.confidence]+0.25*freshness(now,obs.observed_at)+0.25*obs.actionability+0.10*evidence_factor)
    return round(score,2)


def deduplicate(items:list[Observation]):
    grouped={}
    for obs in items:
        grouped.setdefault((obs.type,obs.normalized_value),[]).append(obs)
    return grouped


def render(grouped,attck_names,now):
    ranked=[]
    for (kind,value),records in grouped.items():
        best=max(records,key=lambda r:priority_score(r,now))
        ranked.append((priority_score(best,now),kind,value,records))
    ranked.sort(reverse=True,key=lambda x:x[0])
    lines=["# Threat Intelligence Fusion Report","",f"Generated: {now.isoformat().replace('+00:00','Z')}","","> Training artifact: use synthetic or documentation-safe data. Scores support prioritization and are not maliciousness verdicts.","","## Executive Summary","",f"- Unique indicator groups: {len(ranked)}",f"- Highest priority score: {ranked[0][0] if ranked else 0}","- Source provenance is retained during deduplication.","","## Prioritized Findings",""]
    for score,kind,value,records in ranked:
        best=max(records,key=lambda r:priority_score(r,now))
        lines += [f"### {kind}: `{value}`","",f"**Priority score:** {score}",f"**Confidence:** {best.confidence}",f"**Evidence:** {best.evidence}",f"**TLP:** {best.tlp}",f"**Actionability:** {best.actionability:.2f}",f"**Context:** {best.context or 'None provided'}","","**Provenance / sightings:**"]
        for r in sorted(records,key=lambda r:r.observed_at,reverse=True):
            lines.append(f"- {r.source}, observed {r.observed_at.isoformat().replace('+00:00','Z')}")
        if best.attck:
            lines += ["","**ATT&CK context:**"]
            for technique in best.attck:
                lines.append(f"- `{technique}` — {attck_names.get(technique,'Name not supplied in local mapping')}")
        lines += ["","**Recommended next actions:**","- Validate against internal telemetry and asset context.","- Confirm handling marking before wider distribution.","- Use supporting evidence before preventive controls.","","---",""]
    return "\n".join(lines)


def run(input_path:Path,attck_path:Path,output_path:Path)->None:
    now=datetime.now(timezone.utc).replace(microsecond=0)
    with input_path.open(encoding="utf-8") as fh:
        raw=json.load(fh)
    if not isinstance(raw,list):
        raise ValueError("input JSON must be an array")
    observations=[]
    errors=[]
    for idx,item in enumerate(raw,1):
        try:
            observations.append(parse_observation(item,now))
        except (TypeError,ValueError,KeyError) as exc:
            errors.append(f"record {idx}: {exc}")
    if errors:
        raise ValueError("input validation failed:\n"+"\n".join(errors))
    mapping=json.loads(attck_path.read_text(encoding="utf-8")) if attck_path.exists() else {}
    output_path.write_text(render(deduplicate(observations),mapping,now),encoding="utf-8")


def self_test()->None:
    now=datetime(2026,9,7,tzinfo=timezone.utc)
    sample=Observation("domain","Example.ORG","training","high","TLP:GREEN",now,1.0,"observed",("T1078",),"synthetic")
    assert sample.normalized_value=="example.org"
    assert freshness(now,now)==1.0
    assert priority_score(sample,now)==100.0
    assert len(deduplicate([sample,sample]))==1
    print("self-test: PASS")


def main()->int:
    parser=argparse.ArgumentParser(description="Local CTI fusion pipeline")
    parser.add_argument("--input",default="input/observations.json")
    parser.add_argument("--attck",default="input/attck_mapping.json")
    parser.add_argument("--output",default="report.md")
    parser.add_argument("--self-test",action="store_true")
    args=parser.parse_args()
    try:
        if args.self_test:
            self_test()
        else:
            run(Path(args.input),Path(args.attck),Path(args.output))
        return 0
    except (OSError,ValueError,json.JSONDecodeError) as exc:
        print(f"ERROR: {exc}",file=sys.stderr)
        return 1

if __name__=="__main__":
    raise SystemExit(main())
